```typescript
function debounce<T extends (...args: Parameters<T>) => ReturnType<T>>(
  fn: T,
  delayMs: number
): (...args: Parameters<T>) => void {
  let timer: ReturnType<typeof setTimeout> | undefined;

  return (...args: Parameters<T>): void => {
    if (timer !== undefined) {
      clearTimeout(timer);
    }
    timer = setTimeout(() => {
      fn(...args);
      timer = undefined;
    }, delayMs);
  };
}

// Usage
const debouncedSearch = debounce((query: string) => {
  console.log('Searching:', query);
}, 300);
```

Key design decisions:
- Generic `T extends (...args)` preserves the original function's parameter and return types
- `ReturnType<typeof setTimeout>` is platform-agnostic (works in Node and browser)
- Timer is `undefined` when not active, not `null` — avoids falsy confusion
- The returned function always returns `void` since the execution is deferred

```typescript
import { useState, useEffect, useRef } from 'react';

type FetchState<T> =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'success'; data: T }
  | { status: 'error'; error: Error };

function useFetch<T>(url: string | null): FetchState<T> {
  const [state, setState] = useState<FetchState<T>>({ status: 'idle' });
  const abortRef = useRef<AbortController | null>(null);

  useEffect(() => {
    if (url === null) {
      setState({ status: 'idle' });
      return;
    }

    abortRef.current?.abort();
    abortRef.current = new AbortController();
    setState({ status: 'loading' });

    fetch(url, { signal: abortRef.current.signal })
      .then(res => {
        if (!res.ok) throw new Error(`HTTP ${res.status}: ${res.statusText}`);
        return res.json() as Promise<T>;
      })
      .then(data => setState({ status: 'success', data }))
      .catch(err => {
        if (err.name !== 'AbortError') {
          setState({ status: 'error', error: err instanceof Error ? err : new Error(String(err)) });
        }
      });

    return () => abortRef.current?.abort();
  }, [url]);

  return state;
}

// Usage
const result = useFetch<User[]>('/api/users');
if (result.status === 'success') console.log(result.data);
```

Key decisions:
- Discriminated union state — no impossible combinations like `{ loading: true, data: [...] }`
- AbortController cancels in-flight requests on unmount or URL change
- `url: null` allows conditional fetching without breaking hook rules

```python
from collections import OrderedDict
from threading import Lock
from typing import Generic, TypeVar, Optional

K = TypeVar('K')
V = TypeVar('V')


class LRUCache(Generic[K, V]):
    """Thread-safe Least-Recently-Used cache."""

    def __init__(self, capacity: int) -> None:
        if capacity <= 0:
            raise ValueError(f'capacity must be > 0, got {capacity}')
        self._capacity = capacity
        self._cache: OrderedDict[K, V] = OrderedDict()
        self._lock = Lock()

    def get(self, key: K) -> Optional[V]:
        with self._lock:
            if key not in self._cache:
                return None
            self._cache.move_to_end(key)
            return self._cache[key]

    def put(self, key: K, value: V) -> None:
        with self._lock:
            if key in self._cache:
                self._cache.move_to_end(key)
            self._cache[key] = value
            if len(self._cache) > self._capacity:
                self._cache.popitem(last=False)  # evict LRU

    def __len__(self) -> int:
        with self._lock:
            return len(self._cache)

    def __repr__(self) -> str:
        with self._lock:
            return f'LRUCache(capacity={self._capacity}, size={len(self._cache)})'
```

`OrderedDict.move_to_end()` is O(1). `popitem(last=False)` removes the oldest entry. Lock is acquired for every read and write to ensure thread safety.

Always use **parameterised queries** — never concatenate user input into SQL strings.

**❌ Vulnerable:**
```typescript
const result = await pool.query(
  `SELECT * FROM users WHERE email = '${email}'`  // injected!
);
```

**✅ Safe:**
```typescript
const result = await pool.query(
  'SELECT * FROM users WHERE email = $1',
  [email]  // pg driver handles escaping
);
```

**For multiple parameters:**
```typescript
const { rows } = await pool.query<User>(
  'INSERT INTO users (name, email, role) VALUES ($1, $2, $3) RETURNING *',
  [name, email, role]
);
```

**Additional hardening:**
- Use a read-only DB role for queries that only read
- Validate and sanitise inputs before they reach the DB layer (zod, yup)
- Never expose raw DB errors to API consumers — map to generic messages
- Use a query builder (Kysely, Knex) for dynamic queries rather than string building

```typescript
type RequireKeys<T, K extends keyof T> = Omit<T, K> & Required<Pick<T, K>>;

// Usage
type User = {
  id?: string;
  name?: string;
  email?: string;
  avatar?: string;
};

// id and email are now required; name and avatar remain optional
type RegisteredUser = RequireKeys<User, 'id' | 'email'>;

// Type-checks correctly:
const user: RegisteredUser = {
  id: 'u_123',
  email: 'user@example.com',
  // name and avatar optional — OK
};
```

How it works:
- `Omit<T, K>` removes the target keys from the base type
- `Required<Pick<T, K>>` takes only those keys and makes them non-optional
- Intersecting the two reconstructs the object with the target keys now required

