```python
import time
import logging
from functools import wraps
from typing import Callable, Type, TypeVar

log = logging.getLogger(__name__)
F = TypeVar('F', bound=Callable[..., object])


def retry(
    *,
    max_attempts: int = 3,
    base_delay_s: float = 1.0,
    backoff_factor: float = 2.0,
    exceptions: tuple[Type[Exception], ...] = (Exception,),
) -> Callable[[F], F]:
    """Retry decorator with exponential backoff."""

    def decorator(fn: F) -> F:
        @wraps(fn)
        def wrapper(*args: object, **kwargs: object) -> object:
            delay = base_delay_s
            for attempt in range(1, max_attempts + 1):
                try:
                    return fn(*args, **kwargs)
                except exceptions as exc:
                    if attempt == max_attempts:
                        log.error('%s failed after %d attempts: %s', fn.__name__, max_attempts, exc)
                        raise
                    log.warning('%s attempt %d/%d failed: %s. Retrying in %.1fs',
                                fn.__name__, attempt, max_attempts, exc, delay)
                    time.sleep(delay)
                    delay *= backoff_factor
        return wrapper  # type: ignore[return-value]

    return decorator


# Usage
@retry(max_attempts=4, base_delay_s=0.5, exceptions=(ConnectionError, TimeoutError))
def call_external_api(url: str) -> dict:
    ...
```

Use a **config module** that validates and types env vars at startup, rather than reading `process.env` scattered throughout the codebase.

```typescript
// config.ts
import { z } from 'zod';

const envSchema = z.object({
  NODE_ENV:        z.enum(['development', 'test', 'production']),
  PORT:            z.coerce.number().int().positive().default(3000),
  DATABASE_URL:    z.string().url(),
  OLLAMA_BASE_URL: z.string().url().default('http://localhost:11434'),
  JWT_SECRET:      z.string().min(32),
  LOG_LEVEL:       z.enum(['debug', 'info', 'warn', 'error']).default('info'),
});

const _env = envSchema.safeParse(process.env);

if (!_env.success) {
  console.error('Invalid environment configuration:');
  console.error(_env.error.flatten().fieldErrors);
  process.exit(1);  // fail fast — don't start with broken config
}

export const config = Object.freeze(_env.data);
```

**Usage:**
```typescript
import { config } from './config';
const port = config.PORT;  // number, not string — already coerced
```

**Additional practices:**
- `.env` for local dev, never committed
- `.env.example` committed with all keys, no values
- Secrets injected via CI/CD secrets manager in production, never stored in files

Structure error handling in layers:

**1. Custom error class:**
```typescript
export class AppError extends Error {
  constructor(
    public readonly statusCode: number,
    message: string,
    public readonly code?: string
  ) {
    super(message);
    this.name = 'AppError';
  }
}
```

**2. Route handlers throw, don't respond:**
```typescript
router.get('/users/:id', async (req, res, next) => {
  try {
    const user = await UserService.findById(req.params.id);
    if (!user) throw new AppError(404, 'User not found', 'USER_NOT_FOUND');
    res.json(user);
  } catch (err) {
    next(err);  // always pass to error middleware
  }
});
```

**3. Central error middleware (must be last, 4 params):**
```typescript
app.use((err: unknown, req: Request, res: Response, _next: NextFunction) => {
  if (err instanceof AppError) {
    return res.status(err.statusCode).json({
      error: { code: err.code ?? 'ERROR', message: err.message }
    });
  }
  // Unknown error — don't leak internals
  console.error('Unhandled error:', err);
  res.status(500).json({ error: { code: 'INTERNAL_ERROR', message: 'Something went wrong' } });
});
```

They are not different mechanisms — `async/await` is **syntactic sugar over Promises**.

Every `async` function returns a Promise. Every `await` unwraps a Promise.

```javascript
// Promise chain
fetchUser(id)
  .then(user => fetchPosts(user.id))
  .then(posts => render(posts))
  .catch(err => handleError(err));

// Equivalent with async/await
async function loadUserPosts(id) {
  try {
    const user  = await fetchUser(id);
    const posts = await fetchPosts(user.id);
    render(posts);
  } catch (err) {
    handleError(err);
  }
}
```

**When to use Promises directly:**
- `Promise.all([a, b, c])` — concurrent parallel requests
- `Promise.allSettled()` — wait for all, even failures
- `Promise.race()` — first-to-resolve wins
- Event-driven APIs that naturally produce Promise streams

**Prefer `async/await` for:** sequential async logic — it's more readable and easier to debug (stack traces include the full call chain).

```typescript
function groupBy<T, K extends PropertyKey>(
  items: T[],
  getKey: (item: T) => K
): Record<K, T[]> {
  return items.reduce(
    (acc, item) => {
      const key = getKey(item);
      if (!Object.prototype.hasOwnProperty.call(acc, key)) {
        (acc as Record<K, T[]>)[key] = [];
      }
      (acc as Record<K, T[]>)[key].push(item);
      return acc;
    },
    {} as Record<K, T[]>
  );
}

// Usage
const orders = [
  { id: 1, status: 'pending',   amount: 500 },
  { id: 2, status: 'completed', amount: 1200 },
  { id: 3, status: 'pending',   amount: 300 },
  { id: 4, status: 'cancelled', amount: 800 },
];

const byStatus = groupBy(orders, o => o.status);
// { pending: [...], completed: [...], cancelled: [...] }
```

Note: `Object.groupBy()` is now part of ES2024 and available in Node 21+ / modern browsers. For new projects targeting those environments, prefer the native version.

```typescript
import { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';
import { config } from './config';

export interface AuthenticatedRequest extends Request {
  user: { id: string; role: string };
}

// Sign
export function signToken(payload: { id: string; role: string }): string {
  return jwt.sign(payload, config.JWT_SECRET, {
    expiresIn: '15m',     // short-lived access token
    algorithm: 'HS256',
  });
}

// Verify middleware
export function requireAuth(
  req: Request,
  res: Response,
  next: NextFunction
): void {
  const header = req.headers.authorization;
  if (!header?.startsWith('Bearer ')) {
    res.status(401).json({ error: { code: 'MISSING_TOKEN', message: 'No token provided' } });
    return;
  }

  try {
    const token = header.slice(7);
    const payload = jwt.verify(token, config.JWT_SECRET) as { id: string; role: string };
    (req as AuthenticatedRequest).user = payload;
    next();
  } catch {
    res.status(401).json({ error: { code: 'INVALID_TOKEN', message: 'Token invalid or expired' } });
  }
}
```

**Production rules:**
- Access tokens: 15 minutes. Refresh tokens: 7–30 days, stored httpOnly cookie
- Rotate refresh tokens on each use (refresh token rotation)
- Maintain a server-side revocation list for refresh tokens (Redis)
- Never store JWTs in `localStorage` — vulnerable to XSS

