from dataclasses import dataclass
from datetime import datetime, timezone
from typing import NamedTuple


class DateRange(NamedTuple):
    start: datetime
    end: datetime

    def duration_days(self) -> float:
        return (self.end - self.start).total_seconds() / 86_400


def parse_date_range(range_str: str) -> DateRange:
    """Parse 'YYYY-MM-DDTHH:MM:SSZ/YYYY-MM-DDTHH:MM:SSZ' into a DateRange.

    Raises:
        ValueError: if the string is malformed or end <= start.
    """
    if '/' not in range_str:
        raise ValueError(f'Expected ISO 8601 interval with "/", got: {range_str!r}')

    start_str, end_str = range_str.split('/', maxsplit=1)

    try:
        start = datetime.fromisoformat(start_str.replace('Z', '+00:00'))
        end   = datetime.fromisoformat(end_str.replace('Z', '+00:00'))
    except ValueError as exc:
        raise ValueError(f'Invalid ISO 8601 datetime in range {range_str!r}: {exc}') from exc

    if end <= start:
        raise ValueError(f'end ({end}) must be after start ({start})')

    return DateRange(start=start, end=end)


# Usage
dr = parse_date_range('2026-01-01T00:00:00Z/2026-12-31T23:59:59Z')
print(dr.duration_days())  # ~364.99
```
